import {CATEGORIES,INCOME_CATEGORIES,money,cents,today,month,emptyVault,allBalances,totalBalance,reservedTotal,monthStats,categorySpend,addTransaction,removeTransaction,addGoal,deleteGoal,contributeGoal,withdrawGoal,goalSaved,commuteProjection,recordCommute,monthlyTrend,addRecurring,deleteRecurring,recurringForMonth,payRecurring,id,demoVault} from './core.js';
import {listUsers,createUser,loginUser,persist,backup,restore,changePassword,normalizeUser,endNativeSession} from './vault.js';
const root=document.getElementById('app');
let vault=null, key=null, currentUser=null, demo=false, users=[], view='dashboard', modal=null, txType='expense', goalAction='goal', period=month(), txFilter='all', txSearch='', activeWrite=Promise.resolve(), writing=false, busy=false, installPrompt=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fnum=n=>String((n||0)/100);
const pct=(part,whole)=>whole?Math.min(100,Math.max(0,Math.round(part/whole*100))):0;
const formatDate=d=>{try{return new Intl.DateTimeFormat('pt-MZ',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d+'T12:00:00'));}catch{return d;}};
const ms=period=>{const [year,m]=period.split('-').map(Number);return new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(new Date(year,m-1,1));};
const monthValue=period=>period;
const iconPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',receipt:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',bus:'<rect x="5" y="3" width="14" height="16" rx="3"/><path d="M5 12h14M8 19v2m8-2v2M8 8h2m4 0h2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M20 12a8 8 0 0 0-.1-1l2-1.5-2-3.5-2.3 1a8 8 0 0 0-1.8-1L15.5 3h-4L11 6a8 8 0 0 0-2 1L6.8 6 4.7 9.5 6.7 11a8 8 0 0 0 0 2l-2 1.5L6.8 18l2.3-1a8 8 0 0 0 1.9 1l.5 3h4l.5-3a8 8 0 0 0 1.8-1l2.3 1 2-3.5-2-1.5A8 8 0 0 0 20 12"/>',plus:'<path d="M12 5v14M5 12h14"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M16 14h2"/>',chart:'<path d="M4 20V5M4 20h17M8 15l4-4 3 2 5-7"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m8 10 4 4 4-4"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M5 19h14"/>',shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6z"/><path d="m9 12 2 2 4-4"/>',logout:'<path d="M9 4H5v16h4m5-4 4-4-4-4m-7 4h11"/>',filter:'<path d="M4 7h16M7 12h10m-7 5h4"/>',trash:'<path d="M5 7h14M8 7V4h8v3M7 7l1 13h8l1-13M10 10v7m4-7v7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',check:'<path d="m4 12 5 5 11-11"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M5 21h14"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>'};
const ic=(name,size=18)=>`<svg class="svg-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;
let timer;
function toast(msg,error=false){const el=document.getElementById('toast');el.textContent=msg;el.className='toast show'+(error?' error':'');clearTimeout(timer);timer=setTimeout(()=>el.className='toast',3900);}
function walletOptions(selected='cash',omit=''){return vault.wallets.filter(w=>w.id!==omit).map(w=>`<option value="${esc(w.id)}" ${w.id===selected?'selected':''}>${esc(w.name)} — ${esc(money(allBalances(vault).find(b=>b.id===w.id)?.balance))}</option>`).join('');}
const catOptions=(sel='Transporte',income=false)=> (income?INCOME_CATEGORIES:CATEGORIES.map(c=>c.name)).map(c=>`<option value="${esc(c)}" ${c===sel?'selected':''}>${esc(c)}</option>`).join('');
function title(){return ({dashboard:'Visão geral',transactions:'Movimentos',goals:'Metas de poupança',budgets:'Orçamentos',transport:'Rotina & chapa',accounts:'As minhas contas',recurring:'Pagamentos fixos',settings:'Definições'})[view]||'Visão geral';}
function subTitle(){return ({dashboard:'Sabe para onde vai cada metical.',transactions:'Todos os movimentos, organizados ao detalhe.',goals:'Cada metical guardado aproxima-te dos teus sonhos.',budgets:'Planeia o mês sem perder o controlo.',transport:'O custo real das viagens para a faculdade.',accounts:'Carteira, M-Pesa, e-Mola, banco e poupança.',recurring:'Os compromissos que se repetem, sempre sob controlo.',settings:'Os teus dados, a tua privacidade e as tuas preferências.'})[view];}
const NAV=[['dashboard','home','Início'],['transactions','receipt','Movimentos'],['goals','target','Metas'],['budgets','chart','Orçamentos'],['transport','bus','Meu chapa'],['accounts','wallet','Contas'],['recurring','calendar','Pagamentos fixos'],['settings','settings','Definições']];
function sidebar(){return `<aside class="sidebar"><div class="logo"><div class="brand-mark">B</div><span>bolso<span style="color:#b5a0ff">mz</span><small>O teu dinheiro, com clareza.</small></span></div><div class="nav-label">Menu principal</div><nav class="nav">${NAV.map(([name,sym,label])=>`<button data-action="nav" data-view="${name}" class="${view===name?'active':''}" aria-current="${view===name?'page':'false'}">${ic(sym)}<span>${label}</span></button>`).join('')}</nav><div class="nav-footer"><div class="tiny-tag">✦ TUA TRANQUILIDADE</div><strong>Pequenas escolhas.<br>Grandes conquistas.</strong><p>Regista hoje. Conquista amanhã.</p><button class="btn small neutral" data-action="nav" data-view="goals">Ver as minhas metas ${ic('arrow',13)}</button></div><div class="side-profile"><div class="avatar">${esc(vault.profile.name.slice(0,1).toUpperCase())}</div><div><strong>${esc(vault.profile.name)}</strong><span>${demo?'Modo demonstração':'Dados guardados localmente'}</span></div></div></aside>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Menu mobile">${[['dashboard','home','Início'],['transactions','receipt','Movimentos']].map(([name,sym,label])=>`<button data-action="nav" data-view="${name}" class="${view===name?'active':''}">${ic(sym)}${label}</button>`).join('')}<button data-action="newtx" class="nav-add" aria-label="Adicionar movimento">${ic('plus')}</button>${[['goals','target','Metas'],['settings','settings','Mais']].map(([name,sym,label])=>`<button data-action="nav" data-view="${name}" class="${view===name?'active':''}">${ic(sym)}${label}</button>`).join('')}</nav>`;}
function render(){if(!vault){renderAuth();return;}const displayDate=new Intl.DateTimeFormat('pt-MZ',{day:'2-digit',month:'long'}).format(new Date());root.innerHTML=`<div class="app-shell">${sidebar()}<main class="main"><header class="topline"><div><div class="eyebrow">${esc(displayDate)} • ${demo?'Demonstração':'Conta pessoal'}</div><h1 class="page-title">${title()}</h1><p class="page-desc">${subTitle()}</p></div><div class="top-actions"><button class="pill" data-action="newtx">${ic('plus',15)}<span> Novo movimento</span></button><div class="user-inline"><div class="avatar">${esc(vault.profile.name.slice(0,1).toUpperCase())}</div>${esc(vault.profile.name.split(' ')[0])}</div></div></header>${demo?'<div class="demo-strip"><span>✦ Estás a explorar valores fictícios. Nada é guardado.</span><button class="btn small" data-action="enddemo">Criar conta</button></div>':''}${({'dashboard':dashboard,'transactions':transactions,'goals':goals,'budgets':budgets,'transport':transport,'accounts':accounts,'recurring':recurring,'settings':settings})[view]()}<footer class="footer-note">Os teus dados, sempre sob o teu controlo.</footer></main>${mobileNav()}</div>${modal?renderModal():''}`;}
function renderAuth(mode='login'){const savedMode=root.dataset.authMode||mode;const signup=savedMode==='signup';root.innerHTML=`<div class="auth-shell"><section class="auth-side"><div class="logo"><div class="brand-mark">B</div><span>bolso<span style="color:#bba7ff">mz</span><small>O teu dinheiro, com clareza.</small></span></div><div><div class="eyebrow">A tua vida, bem organizada</div><h1>O teu dinheiro.<br><em>O teu futuro.</em><br>Ao teu ritmo.</h1><p>Da viagem de chapa até à tua próxima grande conquista. Controla cada metical, de forma simples e privada.</p></div><div class="auth-preview"><span class="label">PLANEAMENTO SEM COMPLICAÇÕES</span><strong>Um passo de cada vez.</strong><p>Regista gastos de chapa, acompanha o orçamento e constrói as tuas metas financeiras.</p></div></section><section class="auth-content"><div class="auth-form"><div class="chip" style="display:inline-block">${ic('shield',13)} PRIVADO. SIMPLES. TEU.</div><h2>${signup?'Criar a minha conta':'Bem-vindo de volta'}</h2><p>${signup?'Cria um cofre privado no teu dispositivo para começares a gerir as tuas finanças.':'Entra no teu cofre pessoal. Os teus dados financeiros estão encriptados no dispositivo.'}</p><form id="${signup?'signup-form':'login-form'}">${signup?`<div class="field"><label for="auth-name">Como devemos chamar-te?</label><input required maxlength="60" class="input" id="auth-name" name="name" placeholder="O teu nome" autocomplete="name"></div>`:''}<div class="field"><label for="auth-id">Identificador da conta</label><input required minlength="3" maxlength="80" class="input" id="auth-id" name="id" placeholder="ex.: meu.bolso" value="${!signup&&users.length===1?esc(users[0].id):''}" autocomplete="username" autocapitalize="none"></div><div class="field"><label for="auth-pass">Palavra-passe</label><div class="password-input"><input required minlength="${signup?10:1}" type="password" class="input" id="auth-pass" name="password" placeholder="${signup?'Mínimo de 10 caracteres':'A tua palavra-passe'}" autocomplete="${signup?'new-password':'current-password'}"><button class="password-toggle" type="button" data-action="passvis" data-target="auth-pass" aria-label="Mostrar palavra-passe" aria-pressed="false">Mostrar</button></div></div>${signup?`<div class="field"><label for="auth-confirm">Confirmar palavra-passe</label><input required minlength="10" type="password" class="input" id="auth-confirm" name="confirm" placeholder="Repete a palavra-passe" autocomplete="new-password"></div>`:''}<button class="btn primary full" type="submit">${signup?'Criar cofre privado':'Entrar no BolsoMZ'} ${ic('arrow')}</button></form><div class="auth-switch">${signup?'Já tens uma conta neste dispositivo?':'Ainda não tens conta?'} <button data-action="authmode" data-mode="${signup?'login':'signup'}">${signup?'Entrar':'Criar conta'}</button></div><div class="auth-extra"><input type="file" id="restore-file" accept=".json,application/json" hidden><button class="text-btn" data-action="choosebackup">${ic('upload',14)} Restaurar cópia encriptada</button><p class="smallprint">Sem servidor e sem sincronização automática. Guarda cópias de segurança: se perderes a palavra-passe, não será possível recuperar os dados.</p></div></div></section></div>`;}
function overviewStat(label,value,detail,color='#ae93ff'){return `<div class="stat-card"><div class="label"><i class="dot" style="background:${color}"></i>${label}</div><div class="value">${money(value)}</div><div class="detail">${esc(detail)}</div></div>`;}
function dashboard(){const stats=monthStats(vault,period),total=totalBalance(vault),saved=reservedTotal(vault),pro=commuteProjection(vault),mainGoal=vault.goals[0],trend=monthlyTrend(vault),peak=Math.max(...trend.flatMap(t=>[t.income,t.expense]),1),expenseCats=categorySpend(vault,period).filter(c=>c.spent>0).sort((a,b)=>b.spent-a.spent),sum=stats.expense;
 let start=0;const grad=expenseCats.length?`conic-gradient(${expenseCats.map(c=>{const a=start;start+=c.spent/sum*100;return `${c.color} ${a}% ${start}%`;}).join(',')})`:'#2a2839';
 return `<div class="grid-hero"><section class="hero"><div class="hero-head"><span>${ic('wallet',16)} Saldo total das tuas contas</span><span class="mini-logo">B</span></div><div class="hero-balance">${money(total)}</div><div class="hero-bottom"><div><small>Disponível sem metas</small><strong>${money(total-saved)}</strong></div><div class="hero-line"></div><div><small>Reservado para metas</small><strong>${money(saved)}</strong></div></div></section><section class="soft-panel card-transport"><div class="card-header"><span class="chip">${ic('bus',13)} TRANSPORTE</span><span class="transport-icon">🚌</span></div><div><div class="stat-caption">Previsão de chapa por mês</div><div class="stat-big">${money(pro.month)}</div><div class="stat-caption">${vault.commute.tripsPerDay} viagem(ns)/dia · ${vault.commute.daysPerMonth} dias de aulas</div></div><div class="transport-foot"><div><span>Por dia</span><br><strong>${money(pro.day)}</strong></div><button class="text-btn" data-action="nav" data-view="transport">Minha rotina ${ic('arrow',13)}</button></div></section></div><div class="stat-grid">${overviewStat('Entradas no mês',stats.income,ms(period),'#a7dda7')}${overviewStat('Saídas no mês',stats.expense,ms(period),'#f6adae')}${overviewStat('Guardado este mês',stats.saved,'Transferido para metas','#c5a8ff')}</div><div class="cols"><section class="soft-panel"><div class="section-head"><div><h3>Fluxo financeiro</h3><p>Entradas versus despesas • últimos seis meses</p></div><span class="chip">6 MESES</span></div><div class="chart-bars">${trend.map(t=>`<div class="bar-group" title="${esc(ms(t.period))}: ${money(t.income)} entradas / ${money(t.expense)} despesas"><div class="bar inc" style="height:${Math.max(3,t.income/peak*100)}%"></div><div class="bar out" style="height:${Math.max(3,t.expense/peak*100)}%"></div></div>`).join('')}</div><div class="chart-labels">${trend.map(t=>`<span>${esc(t.label)}</span>`).join('')}</div><div class="legend"><span><b></b> Entradas</span><span><b class="purple"></b> Despesas</span></div></section><section class="soft-panel"><div class="section-head"><div><h3>Para onde foi o dinheiro?</h3><p>Despesas em ${ms(period)}</p></div><button class="text-btn" data-action="nav" data-view="budgets">Orçamentos</button></div><div class="donut-row"><div class="donut" style="background:${grad}"><div class="donut-label"><strong>${sum?expenseCats.length:0}</strong><small>categorias</small></div></div><div class="category-legend">${expenseCats.length?expenseCats.slice(0,4).map(c=>`<div class="c-row"><span><i style="background:${c.color}"></i>${esc(c.name)}</span><b>${pct(c.spent,sum)}%</b></div>`).join(''):'<p class="stat-caption">Regista despesas para acompanhar os teus hábitos.</p>'}</div></div></section></div><div class="cols"><section class="soft-panel"><div class="section-head"><div><h3>Últimos movimentos</h3><p>O teu histórico financeiro recente</p></div><button class="text-btn" data-action="nav" data-view="transactions">Ver todos ${ic('arrow',13)}</button></div>${vault.transactions.length?vault.transactions.slice().sort(sortTx).slice(0,5).map(t=>renderTxRow(t)).join(''):empty('💳','Ainda não há movimentos','Começa por registar uma entrada, como uma mesada, bolsa ou salário.','newtx','Registar movimento')}</section><section class="soft-panel"><div class="section-head"><div><h3>Sonhos em construção</h3><p>O progresso das tuas metas</p></div><button class="text-btn" data-action="nav" data-view="goals">Ver metas ${ic('arrow',13)}</button></div>${vault.goals.length?vault.goals.slice(0,2).map(renderGoalMini).join(''):empty('🎯','Qual é o teu próximo sonho?','Define quanto precisas para um computador, curso ou outro objetivo.','newgoal','Criar uma meta')}</section></div>${billPeek()}${insight(stats)}</div>`;
}
function insight(s){const monthly=commuteProjection(vault).month, portion=s.expense?pct(monthly,s.expense):0;return `<div class="insight-strip">✦ <strong>O teu pequeno conselho:</strong> ${s.expense?`Este mês já registaste <strong>${money(s.expense)}</strong> em despesas. A previsão de chapa representa cerca de <strong>${portion}%</strong> desse valor (estimativa, não gasto registado).`:'Começa por anotar os teus gastos durante uma semana. Vais perceber rapidamente onde podes poupar sem sacrificar o essencial.'}</div>`;}

function billPeek(){
 const upcoming=recurringForMonth(vault).filter(b=>!b.paid);
 if(!(vault.recurring||[]).length)return `<section class="soft-panel" style="margin-top:18px"><div class="section-head"><div><h3>Pagamentos do mês</h3><p>Organiza as despesas que se repetem</p></div><button class="btn small neutral" data-action="nav" data-view="recurring">Configurar ${ic('arrow',13)}</button></div><p class="section-desc">Regista internet, mensalidades, subscrições e outras despesas fixas. Nada será debitado sem a tua confirmação.</p></section>`;
 return `<section class="soft-panel" style="margin-top:18px"><div class="section-head"><div><h3>Pagamentos por fazer</h3><p>${upcoming.length} pendente(s) neste mês</p></div><button class="text-btn" data-action="nav" data-view="recurring">Ver todos ${ic('arrow',13)}</button></div>${upcoming.length?upcoming.slice(0,3).map(b=>`<div class="trans-row"><div class="tx-icon">📅</div><div class="trans-info"><strong>${esc(b.name)}</strong><small>Dia ${b.dueDate.slice(-2)} · ${esc(b.category)}</small></div><div class="trans-amount"><strong>${money(b.amount)}</strong><small>${b.status==='late'?'Vencido':'Previsto'}</small></div></div>`).join(''):'<p class="success-text">✓ Os pagamentos fixos deste mês estão em dia.</p>'}</section>`;
}
function recurring(){
 const list=recurringForMonth(vault,period), pending=list.filter(b=>!b.paid),total=pending.reduce((n,b)=>n+b.amount,0);
 return `<section class="recurring-banner"><div><span class="chip">${ic('calendar',13)} PLANEAMENTO MENSAL</span><h2>Os teus pagamentos. Sem surpresas.</h2><p>Organiza os compromissos do mês e regista cada pagamento uma única vez.</p></div><div><small>Ainda por pagar em ${esc(ms(period))}</small><strong>${money(total)}</strong></div></section>
 <section class="soft-panel"><div class="section-head"><div><h3>Calendário de pagamentos</h3><p>${list.length} despesa(s) fixa(s) · pagamentos apenas mediante confirmação</p></div><button class="btn small primary" data-action="newrecurring">${ic('plus',14)} Novo pagamento</button></div>
 <form id="billperiod-form" class="filter-row"><input aria-label="Mês de pagamentos" type="month" name="month" class="input" style="max-width:190px" required value="${esc(period)}"><button class="btn small" type="submit">Ver mês</button></form>
 ${list.length?list.map(b=>`<div class="bill-row"><div class="bill-day"><strong>${b.dueDate.slice(-2)}</strong><span>${esc(ms(period).split(' ')[0].slice(0,3).toUpperCase())}</span></div><div class="bill-copy"><strong>${esc(b.name)}</strong><small>${esc(b.category)} · ${esc(vault.wallets.find(w=>w.id===b.walletId)?.name||'Conta')}</small><span class="bill-state ${b.paid?'paid':b.status==='late'?'late':''}">${b.paid?'✓ Pago':b.status==='late'?'Vencido':'Por pagar'}</span></div><div class="bill-right"><strong>${money(b.amount)}</strong><div class="hstack"><button ${b.paid?'disabled':''} class="btn small ${b.paid?'':'primary'}" data-action="payrecurring" data-id="${esc(b.id)}">${b.paid?'Pago':'Registar pagamento'}</button><button class="table-action" title="Eliminar regra mensal" aria-label="Eliminar pagamento fixo" data-action="deleterecurring" data-id="${esc(b.id)}">${ic('trash',15)}</button></div></div></div>`).join(''):empty('🗓️','Ainda não tens pagamentos fixos','Adiciona os teus gastos regulares para não te esqueceres do que tens a pagar.','newrecurring','Criar pagamento fixo')}
 </section><div class="insight-strip">${ic('info',15)} Os pagamentos não saem automaticamente das tuas contas reais. Ao confirmares, a app regista a despesa na conta que escolheste. Podes eliminar a regra sem apagar despesas antigas.</div>`;
}
function empty(emoji,t,desc,action,label){return `<div class="empty"><span class="emoji">${emoji}</span><strong>${esc(t)}</strong><p>${esc(desc)}</p>${action?`<button class="btn small neutral" data-action="${action}">${esc(label)}</button>`:''}</div>`;}
function sortTx(a,b){return b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt);}
function txMeta(tx){if(tx.type==='income')return {emoji:'↙',title:tx.note||tx.category||'Entrada',color:'positive',sign:'+'};if(tx.type==='expense'){const cat=CATEGORIES.find(c=>c.name===tx.category);return {emoji:cat?.icon||'🧾',title:tx.note||tx.category,color:'negative',sign:'−'};}if(tx.type==='goal')return {emoji:'🎯',title:tx.note||'Poupança para meta',color:'transfer',sign:'↗'};if(tx.type==='unreserve')return {emoji:'↩️',title:tx.note||'Levantamento da meta',color:'transfer',sign:'↗'};return {emoji:'⇄',title:tx.note||'Transferência',color:'transfer',sign:'↗'};}
function renderTxRow(tx,canDelete=false){const m=txMeta(tx),account=tx.walletId||tx.fromWallet;const w=vault.wallets.find(w=>w.id===account);return `<div class="trans-row"><div class="tx-icon">${m.emoji}</div><div class="trans-info"><strong>${esc(m.title)}</strong><small>${esc(formatDate(tx.date))} · ${esc(w?.name||'Conta')} ${tx.type==='transfer'?'→ '+esc(vault.wallets.find(w=>w.id===tx.toWallet)?.name||''):''}</small></div><div class="trans-amount"><strong class="${m.color}">${m.sign} ${money(tx.amount)}</strong><small>${tx.type==='income'?'Entrada':tx.type==='expense'?esc(tx.category):'Movimentação'}</small></div>${canDelete?`<button class="table-action" title="Eliminar este movimento" aria-label="Eliminar movimento" data-action="deletetx" data-id="${esc(tx.id)}">${ic('trash',16)}</button>`:''}</div>`;}
function renderGoalMini(g){const saved=goalSaved(vault,g.id);return `<div class="goal-preview"><div class="goal-top"><div class="goal-emoji">${esc(g.emoji)}</div><div><strong>${esc(g.name)}</strong><small>Meta: ${money(g.target)}</small></div></div><div class="progress"><span style="width:${pct(saved,g.target)}%"></span></div><div class="goal-bottom"><span>${money(saved)} guardados</span><strong>${pct(saved,g.target)}%</strong></div></div>`;}
function transactions(){const all=vault.transactions.filter(t=>t.date.startsWith(period)).filter(t=>txFilter==='all'||t.type===txFilter).filter(t=>!txSearch||[t.note,t.category,vault.wallets.find(w=>w.id===(t.walletId||t.fromWallet))?.name].join(' ').toLowerCase().includes(txSearch.toLowerCase())).sort(sortTx);return `<section class="soft-panel"><div class="section-head"><div><h3>Histórico de transações</h3><p>${all.length} movimento(s) encontrados · os valores são manuais</p></div><button class="btn small primary" data-action="newtx">${ic('plus',14)} Adicionar</button></div><form class="filter-row" id="search-form"><input aria-label="Pesquisar transações" class="input" name="query" placeholder="Pesquisar descrição ou categoria…" value="${esc(txSearch)}"><select class="select" name="filter"><option value="all" ${txFilter==='all'?'selected':''}>Todos os tipos</option><option value="expense" ${txFilter==='expense'?'selected':''}>Despesas</option><option value="income" ${txFilter==='income'?'selected':''}>Entradas</option><option value="transfer" ${txFilter==='transfer'?'selected':''}>Transferências</option><option value="goal" ${txFilter==='goal'?'selected':''}>Reservas</option></select><input class="input" style="max-width:175px" aria-label="Mês de pesquisa" type="month" name="month" value="${esc(period)}" required><button class="btn small" type="submit">${ic('filter',13)} Filtrar</button></form>${all.length?all.map(t=>renderTxRow(t,true)).join(''):empty('🔍','Não foram encontrados movimentos','Experimenta outro período ou adiciona uma nova transação.','newtx','Registar movimento')}</section>`;}
function goals(){const saved=reservedTotal(vault);return `<section class="soft-panel" style="margin-bottom:18px"><div class="split-between"><div><div class="eyebrow">TOTAL RESERVADO</div><div class="stat-big" style="margin-bottom:0">${money(saved)}</div><p class="stat-caption">Acompanha os valores que separaste para objetivos concretos.</p></div><button class="btn primary" data-action="newgoal">${ic('plus',15)} Nova meta</button></div></section>${vault.goals.length?`<div class="goals-grid">${vault.goals.map(g=>{const s=goalSaved(vault,g.id),rest=Math.max(0,g.target-s),months=g.deadline?Math.max(1,(new Date(g.deadline+'T12:00:00')-new Date())/(1000*60*60*24*30.4)):null;return `<section class="soft-panel"><div class="split-between"><span class="goal-emoji">${esc(g.emoji)}</span><span class="badge">${pct(s,g.target)}%</span></div><h3 style="font-size:16px;margin:19px 0 6px">${esc(g.name)}</h3><p class="stat-caption">${g.deadline?'Até '+esc(formatDate(g.deadline)):'Sem data-limite'}</p><div class="stat-big">${money(s)}</div><div class="progress"><span style="width:${pct(s,g.target)}%"></span></div><div class="goal-bottom"><span>Faltam ${money(rest)}</span><strong>Meta ${money(g.target)}</strong></div>${months&&rest?`<div class="insight-strip">Para alcançares a meta a tempo, reserva cerca de <strong>${money(Math.ceil(rest/months))}/mês</strong>.</div>`:''}<div class="hstack" style="margin-top:20px;flex-wrap:wrap"><button class="btn primary small" data-action="goalflow" data-goal="${esc(g.id)}" data-flow="goal">${ic('plus',13)} Guardar</button><button class="btn small" data-action="goalflow" data-goal="${esc(g.id)}" data-flow="unreserve">Retirar</button><button class="table-action" title="Eliminar meta vazia" data-action="deletegoal" data-id="${esc(g.id)}">${ic('trash',15)}</button></div></section>`;}).join('')}</div>`:empty('🎯','O teu futuro começa com uma meta','Criar um objetivo permite acompanhar quanto já guardaste e quanto ainda falta.','newgoal','Criar meta de poupança')}`;}
function budgets(){const data=categorySpend(vault,period);const totalBudget=Object.values(vault.budgets).reduce((a,b)=>a+b,0),totalSpent=data.reduce((a,b)=>a+b.spent,0);return `<div class="stat-grid">${overviewStat('Orçamento mensal',totalBudget,ms(period),'#b69cff')}${overviewStat('Despesas registadas',totalSpent,ms(period),'#f5aeaf')}${overviewStat('Diferença prevista',totalBudget-totalSpent,'Orçamento menos despesas','#a5dcab')}</div><section class="soft-panel"><div class="section-head"><div><h3>Limites por categoria</h3><p>Define quanto pretendes gastar por mês</p></div><button class="btn small primary" data-action="editbudget">${ic('plus',14)} Editar limites</button></div><p class="smallprint">As barras mostram o gasto real de ${ms(period)} comparado com os limites que configuraste.</p>${data.map(c=>{const budget=vault.budgets[c.name]||0;return `<div class="budget-line"><div class="budget-title"><span>${c.icon}</span> ${esc(c.name)}</div><div class="mini-progress"><div class="${budget&&c.spent>budget?'over':''}" style="width:${pct(c.spent,budget)||(!budget&&c.spent?100:0)}%"></div></div><div class="budget-sum">${money(c.spent)}<em>de ${budget?money(budget):'sem limite'}</em></div></div>`;}).join('')}</section>`;}
function transport(){const c=vault.commute,p=commuteProjection(vault),periodTransactions=vault.transactions.filter(t=>t.date.startsWith(period)&&t.category==='Transporte'&&t.type==='expense'),actual=periodTransactions.reduce((s,t)=>s+t.amount,0),wasToday=vault.transactions.some(t=>t.commuteDate===today());return `<div class="grid-hero"><section class="hero"><div class="hero-head"><span>🚌 A tua rotina • xapa / chapa</span><span class="mini-logo">↗</span></div><div class="eyebrow" style="margin-top:24px;color:#e1d4f9">ESTIMATIVA MENSAL</div><div class="hero-balance">${money(p.month)}</div><div class="hero-bottom"><div><small>Por dia</small><strong>${money(p.day)}</strong></div><div class="hero-line"></div><div><small>Por ano</small><strong>${money(p.year)}</strong></div></div></section><section class="soft-panel card-transport"><div class="card-header"><span class="chip">REGISTADO ESTE MÊS</span><span class="transport-icon">🚐</span></div><div class="stat-big">${money(actual)}</div><p class="stat-caption">Despesas em Transporte que registaste, incluindo dias de aulas.</p><button class="btn primary full" data-action="recordcommute" ${wasToday?'disabled':''}>${wasToday?ic('check'):ic('plus')} ${wasToday?'Chapa de hoje registado':'Registar chapa de hoje'}</button></section></div><div class="cols" style="margin-top:18px"><section class="soft-panel"><div class="section-head"><div><h3>Calculadora da rotina</h3><p>Personaliza a previsão conforme as tuas viagens</p></div></div><form id="commute-form" class="fields"><div class="field"><label>Preço de cada viagem (MT)</label><input class="input" name="oneWay" required type="number" min="0.01" step="0.01" value="${fnum(c.oneWay)}"></div><div class="field"><label>Viagens por dia</label><input class="input" name="trips" required type="number" min="1" max="8" step="1" value="${c.tripsPerDay}"></div><div class="field"><label>Dias de aulas por mês</label><input class="input" name="days" required type="number" min="1" max="31" step="1" value="${c.daysPerMonth}"></div><div class="field"><label>De que conta sai o dinheiro?</label><select class="select" name="wallet">${walletOptions(c.walletId)}</select></div><div class="field span2"><button type="submit" class="btn primary">Guardar a minha rotina ${ic('check',14)}</button></div></form></section><section class="soft-panel"><div class="section-head"><h3>Quanto custa ir à faculdade?</h3></div><div class="trans-row"><div class="tx-icon">↗</div><div class="trans-info"><strong>Uma viagem</strong><small>Preço unitário</small></div><div class="trans-amount"><strong>${money(c.oneWay)}</strong></div></div><div class="trans-row"><div class="tx-icon">🚐</div><div class="trans-info"><strong>Um dia</strong><small>${c.tripsPerDay} deslocação(ões)</small></div><div class="trans-amount"><strong>${money(p.day)}</strong></div></div><div class="trans-row"><div class="tx-icon">📅</div><div class="trans-info"><strong>Um mês</strong><small>${c.daysPerMonth} dias de aulas</small></div><div class="trans-amount"><strong>${money(p.month)}</strong></div></div><div class="trans-row"><div class="tx-icon">🎓</div><div class="trans-info"><strong>Um ano</strong><small>12 meses hipotéticos</small></div><div class="trans-amount"><strong>${money(p.year)}</strong></div></div><div class="insight-strip">Esta previsão não é debitada automaticamente. O botão <strong>Registar chapa de hoje</strong> cria uma despesa real, uma vez por data.</div></section></div>`;}
function accounts(){const all=allBalances(vault);return `<section class="soft-panel" style="margin-bottom:18px"><div class="section-head"><div><h3>Saldo global</h3><p>Soma dos saldos de todas as contas financeiras</p><div class="stat-big" style="margin-top:10px">${money(totalBalance(vault))}</div></div><div class="hstack"><button class="btn small neutral" data-action="newtx" data-kind="transfer">${ic('arrow',13)} Transferir</button><button class="btn small primary" data-action="newwallet">${ic('plus',13)} Conta</button></div></div></section><div class="wallet-grid">${all.map(w=>`<section class="wallet-card"><div class="wallet-card-head"><span class="wallet-name">${esc(w.name)}</span><span class="icon" style="color:${esc(w.color||'#bba3ff')}">${ic('wallet',18)}</span></div><strong>${money(w.balance)}</strong><small>${w.type==='savings'?'Dinheiro reservado ou disponível na poupança':'Saldo calculado pelos movimentos'}</small></section>`).join('')}</div><div class="notice" style="margin-top:18px">${ic('info',15)} Os saldos são calculados a partir dos movimentos que registas. Esta aplicação não comunica com o M-Pesa, e-Mola ou bancos. O dinheiro físico continua nas tuas contas reais.</div>`;}
function settings(){return `<section class="soft-panel" style="margin-bottom:18px"><div class="section-head"><div><h3>Acesso rápido</h3><p>As outras ferramentas do teu BolsoMZ</p></div></div><div class="hstack" style="flex-wrap:wrap"><button class="btn neutral" data-action="nav" data-view="transport">${ic('bus')} Rotina de chapa</button><button class="btn neutral" data-action="nav" data-view="budgets">${ic('chart')} Orçamentos</button><button class="btn neutral" data-action="nav" data-view="accounts">${ic('wallet')} Contas</button><button class="btn neutral" data-action="nav" data-view="recurring">${ic('calendar')} Pagamentos fixos</button></div></section><div class="settings-grid"><section class="soft-panel settings-section"><div class="section-head"><h3>${ic('shield',18)} Privacidade e cópias</h3></div><p>A base de dados está neste dispositivo, e os dados financeiros ficam protegidos por AES-GCM com chave derivada da tua palavra-passe.</p><div class="notice">Sem conta na nuvem nem recuperação de palavra-passe. Exporta um backup regularmente; a sua importação exige a mesma palavra-passe.</div><div class="hstack" style="margin-top:20px;flex-wrap:wrap"><button class="btn primary" data-action="backup">${ic('download',14)} Exportar backup</button><button class="btn" data-action="csv">${ic('download',14)} CSV de movimentos</button></div></section><section class="soft-panel settings-section"><div class="section-head"><h3>${ic('wallet',18)} A minha conta local</h3></div><div class="side-profile"><div class="avatar">${esc(vault.profile.name[0].toUpperCase())}</div><div><strong>${esc(vault.profile.name)}</strong><span>${demo?'Demonstração':esc(currentUser)}</span></div></div><p>Moeda: <strong>Metical moçambicano (MZN)</strong><br>Armazenamento: <strong>${demo?'Temporário / não persistente':'IndexedDB, encriptado'}</strong><br>Utilização: <strong>Offline após a primeira abertura online</strong></p><div class="hstack" style="flex-wrap:wrap; margin-top:14px"><button class="btn" data-action="changepass">${ic('shield',14)} Alterar palavra-passe</button>${globalThis.BolsoMZAndroid?'':`<button class="btn" data-action="install">${ic('download',14)} Instalar no Android</button>`}</div><button class="btn" data-action="logout">${ic('logout',15)} ${demo?'Sair da demonstração':'Bloquear e sair'}</button></section><section class="soft-panel settings-section"><div class="section-head"><h3>Como funciona a poupança?</h3></div><p>Quando adicionas dinheiro a uma meta, o BolsoMZ transfere virtualmente esse valor de uma conta para a conta Poupança. Assim não conta duas vezes o mesmo dinheiro.</p><p>As entradas e saídas são registadas em meticais e guardadas em centavos inteiros para evitar erros de arredondamento.</p></section><section class="soft-panel settings-section"><div class="section-head"><h3>Sobre o BolsoMZ</h3><span class="chip">OFFLINE</span></div><p>Aplicação financeira pessoal concebida para o dia a dia em Moçambique. Inclui despesas, contas, orçamento, pagamentos fixos, rotina de chapa e metas.</p><p class="smallprint">O BolsoMZ ajuda-te a organizar registos pessoais; não movimenta dinheiro real em bancos ou carteiras móveis.</p></section></div>`;}
function fField(label,name,body,extra=''){return `<div class="field ${extra}"><label for="f-${name}">${label}</label>${body}</div>`;}
function modalBox(label,content,footer){return `<div class="modal-backdrop" data-action="backdrop"><section role="dialog" aria-modal="true" aria-label="${esc(label)}" class="modal"><div class="modal-head"><h2>${esc(label)}</h2><button class="icon-btn" data-action="closemodal" aria-label="Fechar">${ic('close')}</button></div>${content}${footer||''}</section></div>`;}
function renderModal(){if(modal.type==='transaction'){const income=txType==='income',transfer=txType==='transfer';let content=`<div class="segment">${[['expense','Despesa'],['income','Entrada'],['transfer','Transferência']].map(([t,l])=>`<button data-action="txtype" data-kind="${t}" class="${t===txType?'current':''}">${l}</button>`).join('')}</div><form id="tx-form" class="fields">${fField('Valor (MT)','amount','<input id="f-amount" name="amount" class="input" type="number" min="0.01" step="0.01" required placeholder="Ex.: 35.00">','span2')}${transfer?`${fField('De onde?','from',`<select id="f-from" name="fromWallet" class="select">${walletOptions('cash')}</select>`)}${fField('Para onde?','to',`<select id="f-to" name="toWallet" class="select">${walletOptions('mpesa')}</select>`)}`:`${fField('Conta financeira','wallet',`<select id="f-wallet" name="walletId" class="select">${walletOptions()}</select>`)}${fField('Categoria','category',`<select id="f-category" name="category" class="select">${catOptions(income?'Mesada':'Transporte',income)}</select>`)}`}${fField('Data','date',`<input id="f-date" name="date" type="date" class="input" required value="${today()}">`)}${fField('Descrição','note',`<input id="f-note" name="note" class="input" maxlength="100" placeholder="Ex.: chapa para faculdade">`,'span2')}<div class="field span2"><button type="submit" class="btn primary full">${ic('check',15)} Guardar ${income?'entrada':transfer?'transferência':'despesa'}</button></div></form>`;return modalBox('Novo movimento',content);}
 if(modal.type==='goal'){return modalBox('Criar meta de poupança',`<p class="section-desc">Um objetivo concreto transforma pequenas economias em progresso visível.</p><form id="goal-form" class="fields">${fField('Nome da meta','name','<input id="f-name" class="input" name="name" required maxlength="55" placeholder="Ex.: Comprar um computador">','span2')}${fField('Valor objetivo (MT)','target','<input id="f-target" class="input" name="target" type="number" step="0.01" min="0.01" required placeholder="Ex.: 25000">')}${fField('Símbolo','emoji','<select class="select" name="emoji" id="f-emoji"><option>🎯</option><option>💻</option><option>📱</option><option>🎓</option><option>🏠</option><option>🛡️</option><option>🚗</option><option>✈️</option></select>')}${fField('Data-limite (opcional)','deadline','<input id="f-deadline" class="input" name="deadline" type="date">','span2')}<div class="field span2"><button class="btn primary full" type="submit">Criar a minha meta ${ic('arrow',14)}</button></div></form>`);}
 if(modal.type==='goalflow'){const g=vault.goals.find(g=>g.id===modal.goalId);if(!g)return '';const isSave=goalAction==='goal';return modalBox(`${isSave?'Guardar dinheiro em':'Retirar dinheiro de'} ${g.name}`,`<div class="notice">Reservado atualmente: <strong>${money(goalSaved(vault,g.id))}</strong> · Objetivo: ${money(g.target)}</div><form class="fields" id="goalflow-form" style="margin-top:17px">${fField('Valor (MT)','amount','<input class="input" id="f-amount" type="number" name="amount" min="0.01" step="0.01" required>','span2')}${fField(isSave?'Retirar da conta':'Devolver à conta','wallet',`<select class="select" id="f-wallet" name="walletId">${walletOptions('cash','savings')}</select>`,'span2')}<div class="field span2"><button class="btn primary full" type="submit">${isSave?'Guardar na meta':'Retirar da meta'}</button></div></form>`);}
 if(modal.type==='budget'){return modalBox('Editar orçamentos mensais',`<p class="section-desc">Introduz valores em MT. Deixa em branco ou coloca zero para não definir um limite.</p><form class="fields" id="budget-form">${CATEGORIES.map(c=>fField(`${c.icon} ${c.name}`,c.name,`<input id="f-${esc(c.name)}" class="input" name="${esc(c.name)}" type="number" min="0" step="0.01" placeholder="Sem limite" value="${vault.budgets[c.name]?fnum(vault.budgets[c.name]):''}">`)).join('')}<div class="field span2"><button type="submit" class="btn primary full">Guardar limites ${ic('check',14)}</button></div></form>`);}
 if(modal.type==='recurring'){return modalBox('Novo pagamento fixo',`<p class="section-desc">O pagamento será apenas uma previsão até carregares em Registar pagamento.</p><form id="recurring-form" class="fields">${fField('Descrição','name','<input id="f-name" class="input" name="name" required maxlength="65" placeholder="Ex.: Internet de casa">','span2')}${fField('Montante mensal (MT)','amount','<input id="f-amount" class="input" name="amount" type="number" min="0.01" step="0.01" required>')}${fField('Dia de vencimento','dueDay','<input id="f-dueDay" class="input" name="dueDay" type="number" min="1" max="31" step="1" required value="10">')}${fField('Categoria','category',`<select class="select" id="f-category" name="category">${catOptions()}</select>`)}${fField('Pagar com','wallet',`<select class="select" id="f-wallet" name="walletId">${walletOptions()}</select>`)}<div class="field span2"><button class="btn primary full" type="submit">${ic('check',15)} Adicionar pagamento mensal</button></div></form>`);}
 if(modal.type==='password'){return modalBox('Alterar palavra-passe',`<p class="section-desc">O teu cofre será novamente encriptado. As cópias antigas continuam a exigir a palavra-passe antiga.</p><form id="password-form" class="fields">${fField('Palavra-passe atual','old','<input id="f-old" name="old" type="password" class="input" required autocomplete="current-password">','span2')}${fField('Nova palavra-passe','new','<input id="f-new" name="new" type="password" class="input" minlength="10" required autocomplete="new-password">','span2')}${fField('Confirmar nova palavra-passe','confirm','<input id="f-confirm" name="confirm" type="password" class="input" minlength="10" required autocomplete="new-password">','span2')}<div class="field span2"><button class="btn primary full" type="submit">Alterar e reencriptar o cofre</button></div></form>`);}
 if(modal.type==='wallet'){return modalBox('Nova conta financeira',`<p class="section-desc">Cria um novo espaço para organizares o teu dinheiro.</p><form id="wallet-form" class="fields">${fField('Nome da conta','name','<input id="f-name" class="input" name="name" required maxlength="35" placeholder="Ex.: Cofre em casa">','span2')}${fField('Tipo','type','<select class="select" id="f-type" name="type"><option value="cash">Dinheiro</option><option value="mobile">Carteira móvel</option><option value="bank">Banco</option></select>')}${fField('Saldo inicial (MT)','opening','<input id="f-opening" class="input" name="opening" type="number" min="0" step="0.01" value="0">')}<div class="field span2"><button class="btn primary full" type="submit">Criar conta ${ic('check',14)}</button></div></form>`);}
 return '';
}
async function commit(next,message='Alterações guardadas'){
 if(writing)throw new Error('Aguarda um instante: ainda estamos a guardar a alteração anterior.');
 writing=true;
 try {
   if(!demo){const job=persist(currentUser,structuredClone(next),key);activeWrite=job;await job;}
   vault=next;render();toast(demo?'Alteração de demonstração não guardada.':message);
 } catch(error) { render(); throw error; } finally {writing=false;}
}
function closeModal(){modal=null;render();}
function download(filename,content,mime){if(globalThis.BolsoMZAndroid?.saveFile){globalThis.BolsoMZAndroid.saveFile(filename,content,mime);return;}const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
const safeCsv=value=>{let text=String(value??'');if(/^[\s]*[=+\-@]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};
function makeCsv(){const rows=[['Data','Tipo','Categoria','Descrição','Valor MT','Conta origem','Conta destino'],...vault.transactions.slice().sort(sortTx).map(t=>[t.date,t.type,t.category||'',t.note||'',(t.amount/100).toFixed(2),vault.wallets.find(w=>w.id===(t.walletId||t.fromWallet))?.name||'',vault.wallets.find(w=>w.id===t.toWallet)?.name||''])];return '\ufeff'+rows.map(r=>r.map(safeCsv).join(';')).join('\r\n');}
async function runAction(btn){const act=btn.dataset.action;try{if(writing&&['recordcommute','deletegoal','deletetx','payrecurring','deleterecurring'].includes(act))throw new Error('Aguarda a gravação anterior.');if(act==='nav'){view=btn.dataset.view;modal=null;render();window.scrollTo(0,0);}else if(act==='newtx'){modal={type:'transaction'};txType=btn.dataset.kind||'expense';render();}else if(act==='newgoal'){modal={type:'goal'};render();}else if(act==='newrecurring'){modal={type:'recurring'};render();}else if(act==='changepass'){if(demo)throw new Error('Sai da demonstração para alterar uma palavra-passe.');modal={type:'password'};render();}else if(act==='install'){if(globalThis.BolsoMZAndroid){toast('Já estás a usar a versão Android do BolsoMZ.');}else if(installPrompt){const request=installPrompt;installPrompt=null;await request.prompt();}else{toast('No Chrome Android, abre o menu ⋮ e escolhe Instalar aplicação. É preciso HTTPS.');}}else if(act==='newwallet'){modal={type:'wallet'};render();}else if(act==='editbudget'){modal={type:'budget'};render();}else if(act==='goalflow'){modal={type:'goalflow',goalId:btn.dataset.goal};goalAction=btn.dataset.flow;render();}else if(act==='txtype'){txType=btn.dataset.kind;render();}else if(act==='closemodal'){closeModal();}else if(act==='demo'){root.dataset.authMode='login';demo=true;vault=demoVault();view='dashboard';render();}else if(act==='enddemo'||act==='logout'){await activeWrite.catch(()=>{});if(currentUser)endNativeSession(currentUser);demo=false;vault=null;key=null;currentUser=null;modal=null;users=await listUsers();root.dataset.authMode='login';renderAuth();}else if(act==='authmode'){root.dataset.authMode=btn.dataset.mode;renderAuth();}else if(act==='passvis'){const field=document.getElementById(btn.dataset.target);if(field){field.type=field.type==='password'?'text':'password';btn.textContent=field.type==='password'?'Mostrar':'Ocultar';btn.setAttribute('aria-pressed',field.type==='text'?'true':'false');}}else if(act==='recordcommute'){await commit(recordCommute(vault),'Chapa de hoje registado.');}else if(act==='deletegoal'){if(!confirm('Eliminar esta meta? Só é permitido se não houver dinheiro reservado.'))return;await commit(deleteGoal(vault,btn.dataset.id),'Meta eliminada.');}else if(act==='deletetx'){if(!confirm('Eliminar este movimento financeiro?'))return;await commit(removeTransaction(vault,btn.dataset.id),'Movimento eliminado.');}else if(act==='payrecurring'){if(!confirm('Registar esta despesa agora? Esta ação desconta o valor da conta selecionada.'))return;const dueDate=recurringForMonth(vault,period).find(b=>b.id===btn.dataset.id)?.dueDate;await commit(payRecurring(vault,btn.dataset.id,period,period===month()?today():dueDate),'Pagamento do mês registado.');}else if(act==='deleterecurring'){if(!confirm('Eliminar esta regra mensal? As despesas já pagas continuarão no histórico.'))return;await commit(deleteRecurring(vault,btn.dataset.id),'Pagamento mensal removido.');}else if(act==='backup'){if(demo)throw new Error('A demonstração não pode ser exportada. Cria uma conta.');await activeWrite;download(`BolsoMZ-backup-${today()}.json`,await backup(currentUser),'application/json');toast('Cópia de segurança encriptada exportada.');}else if(act==='csv'){download(`BolsoMZ-movimentos-${today()}.csv`,makeCsv(),'text/csv;charset=utf-8');toast('CSV exportado. Guarda-o com cuidado: não está encriptado.');}else if(act==='choosebackup'){document.getElementById('restore-file')?.click();}}catch(e){toast(e.message||'Ocorreu um erro.',true);}}
root.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;if(btn.dataset.action==='backdrop'){if(e.target!==btn)return;closeModal();return;}runAction(btn);});
root.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const submitButton=e.target.querySelector('button[type=submit]');const originalButtonContent=submitButton?.innerHTML;if(submitButton){submitButton.disabled=true;submitButton.textContent='A guardar com segurança…';}const f=e.target,d=new FormData(f),s=k=>String(d.get(k)||'').trim();try{if(f.getAttribute('id')==='signup-form'){
 if(s('password')!==s('confirm'))throw new Error('As palavras-passe não coincidem.');const uid=normalizeUser(s('id')),val=emptyVault(s('name'),uid);key=await createUser({id:uid,name:s('name'),password:s('password'),vault:val});currentUser=uid;vault=val;demo=false;view='dashboard';root.dataset.authMode='login';render();toast('Conta local criada. Bem-vindo ao BolsoMZ!');
}else if(f.getAttribute('id')==='login-form'){const result=await loginUser(s('id'),s('password'));vault=result.vault;key=result.key;currentUser=result.record.id;demo=false;view='dashboard';render();toast('Cofre desbloqueado.');
}else if(f.getAttribute('id')==='tx-form'){const amount=cents(s('amount')),date=s('date'),note=s('note');let t={type:txType,amount,date,note};if(txType==='transfer'){t.fromWallet=s('fromWallet');t.toWallet=s('toWallet');}else{t.walletId=s('walletId');t.category=s('category');}const next=addTransaction(vault,t);modal=null;await commit(next,'Movimento guardado com sucesso.');
}else if(f.getAttribute('id')==='goal-form'){const next=addGoal(vault,{name:s('name'),target:cents(s('target')),deadline:s('deadline'),emoji:s('emoji')});modal=null;await commit(next,'Meta criada.');
}else if(f.getAttribute('id')==='goalflow-form'){const amount=cents(s('amount')),wallet=s('walletId');const next=goalAction==='goal'?contributeGoal(vault,modal.goalId,amount,wallet):withdrawGoal(vault,modal.goalId,amount,wallet);modal=null;await commit(next,goalAction==='goal'?'Dinheiro reservado na tua meta.':'Valor retirado da meta.');
}else if(f.getAttribute('id')==='budget-form'){const data={};for(const c of CATEGORIES){const val=s(c.name);if(val&&Number(val.replace(',','.'))>0)data[c.name]=cents(val);}modal=null;await commit({...vault,budgets:data},'Orçamentos atualizados.');
}else if(f.getAttribute('id')==='wallet-form'){const name=s('name'),type=s('type'),opening=s('opening');if(!name||name.length>35)throw new Error('Introduz um nome válido.');if(vault.wallets.some(w=>w.name.toLowerCase()===name.toLowerCase()))throw new Error('Já existe uma conta com esse nome.');if(!['cash','mobile','bank'].includes(type))throw new Error('Tipo de conta inválido.');const amount=Number(opening)===0?0:cents(opening);modal=null;await commit({...vault,wallets:[...vault.wallets,{id:id(),name,type,opening:amount,color:'#BBA5FF'}]},'Conta financeira criada.');
}else if(f.getAttribute('id')==='commute-form'){const cost=cents(s('oneWay')),trips=Number(s('trips')),days=Number(s('days')),walletId=s('wallet');if(!Number.isInteger(trips)||trips<1||trips>8||!Number.isInteger(days)||days<1||days>31||!vault.wallets.some(w=>w.id===walletId))throw new Error('Valores da rotina inválidos.');await commit({...vault,commute:{oneWay:cost,tripsPerDay:trips,daysPerMonth:days,walletId}},'Rotina atualizada.');
}else if(f.getAttribute('id')==='recurring-form'){
 const next=addRecurring(vault,{name:s('name'),amount:cents(s('amount')),category:s('category'),walletId:s('walletId'),dueDay:Number(s('dueDay'))});modal=null;await commit(next,'Pagamento fixo criado.');
 }else if(f.getAttribute('id')==='password-form'){
 if(s('new')!==s('confirm'))throw new Error('As novas palavras-passe não coincidem.');
 await activeWrite;key=await changePassword(currentUser,s('old'),s('new'));modal=null;render();toast('Cofre reencriptado com nova palavra-passe. Faz uma nova cópia de segurança.');
 }else if(f.getAttribute('id')==='billperiod-form'){
 period=s('month')||month();render();
 }else if(f.getAttribute('id')==='search-form'){txFilter=s('filter');txSearch=s('query');period=s('month')||month();render();}
}catch(err){toast(err.message||'Não foi possível processar o pedido.',true);}finally{busy=false;if(submitButton?.isConnected){submitButton.disabled=false;submitButton.innerHTML=originalButtonContent;}}});
root.addEventListener('change',async e=>{if(e.target?.id!=='restore-file')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>12_000_000)throw new Error('Ficheiro superior ao limite de 12 MB.');const password=prompt('Introduz a palavra-passe da cópia de segurança para verificar e restaurar a conta:');if(password===null)return;const uid=await restore(await file.text(),password);users=await listUsers();root.dataset.authMode='login';renderAuth();toast(`Cópia restaurada para a conta ${uid}. Entra para continuar.`);}catch(err){toast(err.message,true);}finally{e.target.value='';}});
window.bolsoAndroidBack=()=>{if(modal){closeModal();return true;}if(vault&&view!=='dashboard'){view='dashboard';render();return true;}return false;};
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal)closeModal();});
async function initialize(){try{users=await listUsers();renderAuth();if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){root.innerHTML=`<div class="auth-content"><div class="auth-form"><h2>Não foi possível iniciar o BolsoMZ</h2><p>${esc(e.message)}</p><p>Verifica se a aplicação tem armazenamento disponível. Se o problema continuar, não apagues a aplicação antes de exportar uma cópia dos teus dados.</p></div></div>`;}}
initialize();
